/**
 * Auto-reference utilities for document copy operations.
 * Provides consistent reference string formatting for traceability.
 */

/** Prefix on every system-generated remarks line. */
export const AUTO_GENERATED_PREFIX = "Auto Generated";

/**
 * True for system reference lines:
 * - "Auto Generated Based on …" (current)
 * - "Based on …" (legacy)
 */
export const isAutoGeneratedRemarkLine = (line: string): boolean =>
  /^(?:auto\s+generated\s+)?based on\s+/i.test(line.trim());

const withAutoGeneratedPrefix = (basedOnBody: string): string =>
  `${AUTO_GENERATED_PREFIX} ${basedOnBody}`;

/**
 * Document type display names for reference strings.
 */
const DOC_TYPE_DISPLAY_NAMES: Record<string, string> = {
  APCreditMemo: "A/P Credit Memo",
  APInvoice: "A/P Invoice",
  GoodsReceiptPO: "GRPO",
  OutgoingPayment: "Outgoing Payment",
  PurchaseOrder: "Purchase Order",
  PurchaseQuotation: "Purchase Quotation",
};

/**
 * Plural forms of document types for multi-document references.
 */
const DOC_TYPE_PLURALS: Record<string, string> = {
  APCreditMemo: "A/P Credit Memos",
  APInvoice: "A/P Invoices",
  GoodsReceiptPO: "GRPOs",
  OutgoingPayment: "Outgoing Payments",
  PurchaseOrder: "Purchase Orders",
  PurchaseQuotation: "Purchase Quotations",
};

/**
 * Generates a reference string for a single source document.
 * Format: "Auto Generated Based on <CompanyCode> <Source Document Type> <Doc Num>"
 * Company/BP code is optional for legacy lines without it.
 * Example: "Auto Generated Based on C1105 Purchase Quotation 132424"
 */
export function generateSingleSourceReference(
  docType: string,
  docNum: string,
  companyCode?: string | null,
): string {
  const displayName = DOC_TYPE_DISPLAY_NAMES[docType] || docType;
  const code = String(companyCode ?? "").trim();
  if (code) {
    return withAutoGeneratedPrefix(`Based on ${code} ${displayName} ${docNum}`);
  }
  return withAutoGeneratedPrefix(`Based on ${displayName} ${docNum}`);
}

/**
 * Generates a reference string for multiple source documents.
 * Format: "Auto Generated Based on <count> <Document Type Plural>"
 * If mixed types: "Auto Generated Based on <count> Documents"
 */
export function generateMultiSourceReference(
  documents: { docType: string; docNum: string; companyCode?: string | null }[],
): string {
  const count = documents.length;
  if (count === 0) {
    return "";
  }
  if (count === 1) {
    return generateSingleSourceReference(
      documents[0]!.docType,
      documents[0]!.docNum,
      documents[0]!.companyCode,
    );
  }

  // Check if all documents are the same type
  const firstType = documents[0]!.docType;
  const allSameType = documents.every((doc) => doc.docType === firstType);

  if (allSameType) {
    const pluralName = DOC_TYPE_PLURALS[firstType] || "Documents";
    return withAutoGeneratedPrefix(`Based on ${count} ${pluralName}`);
  }

  // Mixed document types
  return withAutoGeneratedPrefix(`Based on ${count} Documents`);
}

/**
 * Generates a short summary of source documents for reference.
 * Shows up to 3 document numbers, then ellipsis if more.
 * Format: "Auto Generated Based on <CompanyCode?> <DocType> <Num1>, <Num2>..."
 */
export function generateShortDocListSummary(
  documents: { docType: string; docNum: string; companyCode?: string | null }[],
): string {
  const count = documents.length;
  if (count === 0) {
    return "";
  }
  if (count === 1) {
    return generateSingleSourceReference(
      documents[0]!.docType,
      documents[0]!.docNum,
      documents[0]!.companyCode,
    );
  }

  // Check if all documents are the same type
  const firstType = documents[0]!.docType;
  const allSameType = documents.every((doc) => doc.docType === firstType);

  const displayName = allSameType ? DOC_TYPE_DISPLAY_NAMES[firstType] || firstType : "Documents";
  const companyCode = String(documents[0]?.companyCode ?? "").trim();
  const allSameCompany =
    Boolean(companyCode) &&
    documents.every((doc) => String(doc.companyCode ?? "").trim() === companyCode);
  const basedOnBody = allSameCompany
    ? `Based on ${companyCode} ${displayName}`
    : `Based on ${displayName}`;

  if (count <= 3) {
    const docNums = documents.map((doc) => doc.docNum).join(", ");
    return withAutoGeneratedPrefix(`${basedOnBody} ${docNums}`);
  }

  // More than 3 documents - show count and first few numbers
  const shownNums = documents
    .slice(0, 3)
    .map((doc) => doc.docNum)
    .join(", ");
  const remaining = count - 3;
  return withAutoGeneratedPrefix(`${basedOnBody} ${shownNums} (+${remaining} more)`);
}

/**
 * Extracts source document metadata from a reference string.
 * Returns null if the reference doesn't match expected format.
 */
export function parseReferenceToSourceDocs(
  reference: string,
): { docType: string; docNum: string }[] | null {
  if (!isAutoGeneratedRemarkLine(reference)) {
    return null;
  }

  // This is a simplified parser - in production you might want more robust parsing
  // For now, we store source metadata separately, so this is mainly for validation
  return null;
}

/**
 * Strips auto-generated reference lines from remarks while preserving user text.
 *
 * Matches:
 * - "Auto Generated Based on …"
 * - legacy "Based on …"
 *
 * During copy-to vendor change confirmation (Yes), only system-generated
 * reference lines are removed; any manual remarks typed by the user remain.
 */
export function stripAutoGeneratedReferences(remarks: string): string {
  if (!remarks) {
    return "";
  }

  const lines = remarks.split("\n");
  const userLines = lines.filter((line) => !isAutoGeneratedRemarkLine(line));

  return userLines.join("\n").trim();
}
